"#uh-ba input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:ew-resize;margin:0}",
"#uh-ba .lb{position:absolute;top:14px;font-family:'Archivo',system-ui,sans-serif;font-weight:800;font-size:12px;letter-spacing:.08em;text-transform:uppercase;padding:5px 11px;border-radius:999px}#uh-ba .lb.l{left:14px;background:var(--uh-red);color:#fff}#uh-ba .lb.r{right:14px;background:#fff;color:var(--uh-wine)}",
"#uh-ba .tx{text-align:left}#uh-ba .tx p{font-size:16px;line-height:1.75}#uh-ba .tx p+p{margin-top:12px!important}#uh-ba .tx b{color:var(--uh-wine)}",
"#uh-ba .nd{margin-top:18px!important;display:flex;gap:12px;align-items:center;background:#fff;border:1px solid var(--uh-line);border-radius:14px;padding:12px 14px}#uh-ba .nd b{font-family:'Archivo',system-ui,sans-serif;font-size:30px;font-weight:900;color:var(--uh-red);line-height:1}#uh-ba .nd span{font-size:13.5px;color:var(--uh-mute)}",
/* MITOS */
"#uh-myths .ls{max-width:920px;margin:0 auto;display:grid;gap:14px}",
"#uh-myths .m{display:grid;grid-template-columns:1fr 1fr;border-radius:18px;overflow:hidden;border:1px solid var(--uh-line);text-align:left;background:#fff}@media(max-width:700px){#uh-myths .m{grid-template-columns:1fr}}",
"#uh-myths .a,#uh-myths .b{padding:18px 20px;display:flex;gap:12px;align-items:flex-start}#uh-myths .a{background:#F4EFF0}#uh-myths .b{background:#fff}",
