/* DISPARADORES */
"#uh-trig .g{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}@media(max-width:960px){#uh-trig .g{grid-template-columns:1fr 1fr}}",
"#uh-trig .t{background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.16);border-radius:18px;padding:20px;text-align:left;transition:background .2s,transform .2s}#uh-trig .t:hover{background:rgba(255,255,255,.12);transform:translateY(-2px)}",
"#uh-trig .t i{width:44px;height:44px;border-radius:12px;background:var(--uh-red);color:#fff;display:flex;align-items:center;justify-content:center;margin-bottom:12px}#uh-trig .t i svg{width:22px;height:22px}",
"#uh-trig h3{color:#fff;font-size:16.5px;font-weight:800;margin-bottom:6px;line-height:1.25}#uh-trig p{font-size:13.5px;color:#F6DDE1;line-height:1.55}",
"#uh-trig .warn{max-width:820px;margin:26px auto 0;background:#fff;color:var(--uh-ink);border-radius:16px;padding:16px 20px;text-align:left;font-size:14.5px;line-height:1.6}#uh-trig .warn b{color:var(--uh-wine)}",
/* MUJER */
"#uh-woman .lay{display:grid;grid-template-columns:.9fr 1.1fr;gap:36px;align-items:center}@media(max-width:860px){#uh-woman .lay{grid-template-columns:1fr}}",
"#uh-woman .ph{border-radius:22px;overflow:hidden;aspect-ratio:1/1}#uh-woman .ph img{width:100%;height:100%;object-fit:cover}",
"#uh-woman .tx{text-align:left}#uh-woman .tx p{font-size:16px;line-height:1.75}#uh-woman .tx p+p{margin-top:12px!important}#uh-woman .tx b{color:var(--uh-wine)}",
"#uh-woman ul{list-style:none;margin:18px 0 0;padding:0;display:grid;gap:10px}#uh-woman li{display:flex;gap:10px;font-size:15px}#uh-woman li i{flex:0 0 22px;height:22px;border-radius:50%;background:var(--uh-pink);color:var(--uh-red);display:flex;align-items:center;justify-content:center;margin-top:2px}#uh-woman li i svg{width:12px;height:12px}",
/* SOLUCIÓN */
"#uh-sol .lay{display:grid;grid-template-columns:1fr 340px 1fr;gap:24px;align-items:center}@media(max-width:960px){#uh-sol .lay{grid-template-columns:1fr}}",
"#uh-sol .fr{background:#fff;border:1px solid var(--uh-line);border-radius:18px;padding:20px;text-align:left;position:relative;overflow:hidden}#uh-sol .fr+.fr{margin-top:14px}#uh-sol .fr:before{content:'';position:absolute;left:0;top:0;bottom:0;width:5px;background:var(--uh-red)}#uh-sol .fr.w:before{background:var(--uh-wine)}#uh-sol .fr.p:before{background:#E2788A}",
