/* PARA QUIÉN */
"#uh-who .cd{width:min(80vw,300px);background:#fff;border:1px solid var(--uh-line);border-radius:18px;overflow:hidden;text-align:left}#uh-who .ph{aspect-ratio:1/1;overflow:hidden}#uh-who .ph img{width:100%;height:100%;object-fit:cover}",
