/* ─────────────────────────────────────────────────────────────────────
   5 · MONTAJE
   ───────────────────────────────────────────────────────────────────── */
var THEME_HOME = [
  "[data-store^='home-']", ".js-home-main-slider", ".js-home-slider", ".section-home", ".home-section",
  "section.section-banners-home", ".js-home-banners", ".js-home-products", ".js-home-categories",
  "footer.js-footer", "footer[data-store='footer']", ".js-footer"
];
function tidyTheme() {
  if (!C.ocultarHomeDelTema) return;
  THEME_HOME.forEach(function (sel) {
    all(sel).forEach(function (el) { if (!el.closest("#uh-root") && el.id !== "uh-root") el.classList.add("uh-off"); });
  });
}
function logoHeader() {
  var hd = one("header.js-head-main") || one(".js-head-main") || one("header"); if (!hd) return;
  var box = one("#logo", hd) || one(".logo-img-container", hd) || one(".logo-text", hd); if (!box || box.hasAttribute("data-uh")) return;
  box.setAttribute("data-uh", "1");
  var a = box.tagName === "A" ? box : (one("a", box) || box);
  a.innerHTML = '<img class="uh-logo" src="' + LOGO_DARK + '" alt="' + safe(C.empresa) + '">';
}
function root() {
  var r = D.getElementById("uh-root"); if (r) return r;
  r = make("div", "uh-root"); r.className = "uh";
  var hd = one("header.js-head-main") || one(".js-head-main") || one("header");
  if (hd && hd.parentNode) hd.parentNode.insertBefore(r, hd.nextSibling);
  else D.body.appendChild(r);
  return r;
}
function addSection(id, html, cls) {
  var s = make("section", id, html); s.className = "uh-sec " + (cls || "");
  root().appendChild(s); reveal(s); return s;
}
function reveal(rootEl) {
  var items = all(".uh-rv", rootEl); if (!items.length) return;
  if (!("IntersectionObserver" in window)) { items.forEach(function (x) { x.classList.add("in"); }); return; }
  var io = new IntersectionObserver(function (es) {
    es.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); } });
  }, { threshold: 0.12, rootMargin: "0px 0px -30px 0px" });
  items.forEach(function (x) { io.observe(x); });
}
function slider(s) {
  var track = one(".uh-track", s), nav = one(".uh-nav", s); if (!track || !nav) return;
  var kids = track.children, dots = one(".uh-dots", nav), prev = one("[data-prev]", nav), next = one("[data-next]", nav);
  dots.innerHTML = Array.prototype.map.call(kids, function () { return "<i></i>"; }).join("");
  function at() { var b = 0, d = 1e9; for (var n = 0; n < kids.length; n++) { var x = Math.abs(kids[n].offsetLeft - track.offsetLeft - track.scrollLeft); if (x < d) { d = x; b = n; } } return b; }
  function go(n) { n = Math.max(0, Math.min(kids.length - 1, n)); track.scrollTo({ left: kids[n].offsetLeft - track.offsetLeft, behavior: "smooth" }); }
  function paint() {
    var n = at(); all("i", dots).forEach(function (d, k) { d.classList.toggle("on", k === n); });
    prev.disabled = track.scrollLeft < 4; next.disabled = track.scrollLeft + track.clientWidth >= track.scrollWidth - 4;
    nav.style.display = track.scrollWidth <= track.clientWidth + 4 ? "none" : "";
  }
  prev.addEventListener("click", function () { go(at() - 1); });
  next.addEventListener("click", function () { go(at() + 1); });
  track.addEventListener("scroll", function () { clearTimeout(track._t); track._t = setTimeout(paint, 60); }, { passive: true });
  window.addEventListener("resize", paint); paint();
}

/* ─────────────────────────────────────────────────────────────────────
   6 · FRANJA DE OFERTA + CINTA
   ───────────────────────────────────────────────────────────────────── */
function adbar() {
  if (one("#uh-adbar") || one("#ux-adbar")) return;
  var bar = make("div", "uh-adbar", '<span class="tt">' + safe(C.oferta) + '</span><span class="cd"><span><b data-d>00</b><small>DÍAS</small></span><em>:</em><span><b data-h>00</b><small>HRS</small></span><em>:</em><span><b data-m>00</b><small>MIN</small></span><em>:</em><span><b data-s>00</b><small>SEG</small></span></span>');
  var tk = make("div", "uh-ticker"), items = C.cinta.map(function (m) { return "<span>" + safe(m) + "</span>"; }).join(""), rep = "";
  for (var k = 0; k < 6; k++) rep += items;
  tk.innerHTML = '<div class="mt">' + rep + rep + "</div>";
  bar.className = tk.className = "uh";
  D.body.insertBefore(tk, D.body.firstChild); D.body.insertBefore(bar, D.body.firstChild);
  var end = C.finOferta ? new Date(C.finOferta) : null;
  function two(n) { return (n < 10 ? "0" : "") + n; }
  function tick() {
    var now = new Date(), e = end && end > now ? end : new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1);
    var s = Math.max(0, Math.floor((e - now) / 1000));
    one("[data-d]", bar).textContent = two(Math.floor(s / 86400)); one("[data-h]", bar).textContent = two(Math.floor(s % 86400 / 3600));
    one("[data-m]", bar).textContent = two(Math.floor(s % 3600 / 60)); one("[data-s]", bar).textContent = two(s % 60);
  }
  tick(); setInterval(tick, 1000);
}

