/* 7.5 · ¿En qué zona está tu número? (medidor interactivo) */
function secMeter() {
  var MIN = 3, MAX = 12;
  function pos(v) { return ((v - MIN) / (MAX - MIN) * 100).toFixed(2) + "%"; }
  var Z = [
    [ICO.check, "Zona objetivo", "Por debajo de 6 mg/dL el ácido úrico se mantiene disuelto. Es el valor que muchas guías médicas buscan en quienes ya tuvieron gota. Sostenerlo es la clave: hidratación, controles y un apoyo diario.", "#1E8E3E"],
    [ICO.clock, "Zona límite", "Estás cerca del punto en que deja de disolverse. Es el momento ideal para actuar, antes de que se empiecen a formar cristales en tus articulaciones.", "#E39B00"],
    [ICO.x, "Zona de cristalización", "Por encima de 6,8 mg/dL el ácido úrico ya no se disuelve del todo en la sangre y puede formar cristales en forma de aguja. Puede pasar meses sin doler, pero se acumula.", "#C8102E"],
    [ICO.x, "Zona de alto riesgo", "Con valores así es muy probable que ya haya depósitos en tus articulaciones y que las crisis sean cada vez más seguidas. Consultá a tu médico y atacá el problema desde varios frentes.", "#6D0F1F"]
  ];
  var s = addSection("uh-meter",
    '<div class="uh-wrap uh-center">' + head("Herramienta", "¿En qué zona está <em>tu ácido úrico?</em>", "Mové el control hasta el valor de tu último análisis y mirá qué está pasando adentro de tu cuerpo.") +
    '<div class="bx uh-rv"><div class="top"><label for="uh-ua">Mi último análisis</label><div class="val"><span data-v>7,8</span><small>mg/dL</small></div></div>' +
    '<div class="scale"><span class="mk" style="left:' + pos(6) + '"><span style="transform:translateX(-100%)">6,0&nbsp;</span></span><span class="mk" style="left:' + pos(6.8) + '"><span style="transform:none">&nbsp;6,8</span></span><span class="mk" style="left:' + pos(9) + '"><span>9,0</span></span>' +
    '<span class="th"></span><input id="uh-ua" type="range" min="' + MIN + '" max="' + MAX + '" step="0.1" value="7.8" aria-label="Valor de ácido úrico en mg/dL"></div>' +
    '<div class="lg"><span>3 mg/dL</span><span>12 mg/dL</span></div>' +
    '<div class="res"><i></i><div><h3></h3><p></p></div></div>' +
    '<p class="nt">Valores orientativos en sangre. Los rangos de referencia pueden variar según el laboratorio, y el valor objetivo lo define tu médico. Esta herramienta no reemplaza una consulta.</p></div>' +
    cta("Quiero ayudar a bajar mi número", "medidor") + "</div>", "pink");
  var rg = one("input", s), th = one(".th", s), v = one("[data-v]", s), res = one(".res", s), sent = false;
  function paint() {
    var x = +rg.value, z = x < 6 ? 0 : x <= 6.8 ? 1 : x < 9 ? 2 : 3;
    th.style.left = pos(x); th.style.borderColor = Z[z][3];
    v.textContent = x.toFixed(1).replace(".", ","); v.style.color = Z[z][3];
    res.className = "res z" + z; one("i", res).innerHTML = Z[z][0]; one("h3", res).textContent = Z[z][1]; one("p", res).textContent = Z[z][2];
  }
  rg.addEventListener("input", paint);
  rg.addEventListener("change", function () { if (!sent) { sent = true; track("urix_home_medidor", { valor: +rg.value }); } });
  paint();
}

