  var S = [["Semanas o meses antes", "Se acumula en silencio", "El riñón no logra eliminar todo. El ácido úrico se deposita como cristales en la articulación. No duele y no te das cuenta."],
           ["De madrugada", "El dolor te despierta", "Tus defensas atacan los cristales. El dedo amanece rojo, hinchado y caliente, como si te clavaran agujas."],
           ["12 a 24 horas", "El pico de la crisis", "No soportás ni la sábana. No podés apoyar el pie ni ponerte el zapato. Se van los días de trabajo y los planes."],
           ["1 a 2 semanas", "Se calma… pero sigue ahí", "El dolor baja y parece que pasó. Pero los cristales siguen en la articulación y la próxima crisis ya se está armando."]];
